ustify-end gap-2"><button @click="showBulk=false" type="button" class="rounded-lg border border-slate-300 bg-white px-5 py-2.5 text-sm font-semibold hover:bg-slate-100">Cancel</button><button @click="saveBulk()" type="button" class="rounded-lg bg-[#0b1f3a] px-5 py-2.5 text-sm font-semibold text-white hover:bg-[#122b4d]"><i class="fa-solid fa-floppy-disk mr-2"></i>Save All</button></div></div></div></div></div>
