  optionValues(type) { const map={"province": ["Aurora", "Bataan", "Bulacan", "Nueva Ecija", "Pampanga", "Tarlac", "Zambales"], "health": ["Healthy", "Under Observation", "Under Treatment", "Needs Follow-up"], "body": ["Poor", "Fair", "Good", "Very Good"], "session": ["Morning", "Noon", "Evening", "Daily Total"], "stage": ["Early Lactation", "Mid Lactation", "Late Lactation", "Dry"], "result": ["Passed", "For Review", "Failed"], "exit": ["Sold", "Mortality", "Culled", "Transferred", "Slaughtered", "Lost / Missing", "Donated", "Other"], "exitstatus": ["Out", "Dead", "Culled", "Lost / Missing", "Transferred"]}; return map[type]||[]; },
  init() { try { const saved=localStorage.getItem(this.storageKey); if(saved!==null){const parsed=JSON.parse(saved);this.records=Array.isArray(parsed)?parsed:[];}else{this.records=[];this.persist();} } catch(e){this.records=[];this.msg('Unable to read browser storage.');} },
  get filteredRecords() { const q=this.search.toLowerCase().trim();return this.records.filter(r=>{const matchesSearch=!q||this.fieldNames.some(f=>String(r[f]??'').toLowerCase().includes(q));const recordYear=String(r.production_date||'').slice(0,4);return matchesSearch&&(!this.filterProvince||r.province===this.filterProvince)&&(!this.filterGroup||String(r.milking_session)===this.filterGroup)&&(!this.filterYear||recordYear===this.filterYear);}); },
  get summaryCards() { const list=this.filteredRecords;return [{title:"Total Records",value:list.length,description:'Based on current filters',icon:"fa-solid fa-list-check"},{title:"Total Milk (L)",value:list.reduce((sum,r)=>sum+(Number(r.milk_volume)||0),0).toFixed(2),description:'Based on current filters',icon:"fa-solid fa-droplets"},{title:"Morning Records",value:list.filter(r=>r.milking_session==='Morning').length,description:'Based on current filters',icon:"fa-solid fa-sun"},{title:"Evening Records",value:list.filter(r=>r.milking_session==='Evening').length,description:'Based on current filters',icon:"fa-solid fa-moon"}]; },
  get yieldByProvince() { const totals={};this.filteredRecords.forEach(r=>{const name=String(r.province||'Not specified');if(!totals[name])totals[name]={name,yield:0,count:0};totals[name].yield+=Number(r.milk_volume)||0;totals[name].count++;});const items=Object.values(totals).sort((a,b)=>b.yield-a.yield||a.name.localeCompare(b.name));const max=Math.max(0,...items.map(x=>x.yield));return items.map(x=>({...x,percent:max>0?x.yield/max*100:0})); },
  get topFarmers() { const totals={};this.records.filter(r=>{const recordYear=String(r.production_date||'').slice(0,4);return (!this.filterYear||recordYear===this.filterYear)&&(!this.filterProvince||r.province===this.filterProvince)&&(!this.leaderSession||r.milking_session===this.leaderSession);}).forEach(r=>{const name=String(r.farmer||'Farmer not specified').trim();if(!totals[name])totals[name]={name,yield:0,count:0};totals[name].yield+=Number(r.milk_volume)||0;totals[name].count++;});const items=Object.values(totals).sort((a,b)=>b.yield-a.yield||a.name.localeCompare(b.name)).slice(0,5);const max=Math.max(0,...items.map(x=>x.yield));return items.map(x=>({...x,percent:max>0?x.yield/max*100:0})); },
  provinceYieldTotal(){return this.filteredRecords.reduce((sum,r)=>sum+(Number(r.milk_volume)||0),0);},
  totalPages(){return Math.max(1,Math.ceil(this.filteredRecords.length/this.perPage));},
  paginatedRecords(){const list=this.filteredRecords;if(this.page>this.totalPages())this.page=this.totalPages();return list.slice((this.page-1)*this.perPage,this.page*this.perPage);},
  options(field){return [...new Set(this.records.map(r=>String(r[field]??'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));},
  distribution(field){const counts={};this.filteredRecords.forEach(r=>{const name=String(r[field]||'Not specified');counts[name]=(counts[name]||0)+1;});const max=Math.max(1,...Object.values(counts));return Object.entries(counts).map(([name,count])=>({name,count,percent:count/max*100})).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));},
  emptyRow(){const r={_key:++this.rowKey};this.fieldNames.forEach(f=>r[f]='');return r;},
  openBulk(){this.bulkRows=[this.emptyRow()];this.showBulk=true;},addRow(){this.bulkRows.push(this.emptyRow());},removeRow(i){this.bulkRows.splice(i,1);},
  addSampleRows(){this.sampleData.forEach(s=>{const r=this.emptyRow();this.fieldNames.forEach(f=>r[f]=s[f]??'');this.bulkRows.push(r);});this.msg('Added sample rows. Review them before saving.');},
  persist(){try{localStorage.setItem(this.storageKey,JSON.stringify(this.records));return true;}catch(e){this.msg('Unable to save browser data. Check browser storage settings.');return false;}},
  saveBulk(){const valid=this.bulkRows.filter(r=>String(r.animal_id ?? '').trim() && String(r.production_date ?? '').trim() && String(r.milking_session ?? '').trim() && String(r.milk_volume ?? '').trim());if(!valid.length){this.msg('Please complete all required fields marked with *.');return;}const prepared=valid.map(r=>{const x={};this.fieldNames.forEach(f=>x[f]=r[f]??'');x.id='rec-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);return x;});const previous=this.records;this.records=[...prepared,...this.records];if(this.persist()){this.showBulk=false;this.page=1;this.msg(prepared.length+' record(s) saved in this browser.');}else this.records=previous;},
  view(r){this.selected={...r};this.showView=true;},remove(id){if(!confirm('Delete this record?'))return;const prev=this.records;this.records=this.records.filter(r=>r.id!==id);if(this.persist())this.msg('Record deleted.');else this.records=prev;},
  resetFilters(){this.search='';this.filterProvince='';this.filterGroup='';this.filterYear='';this.leaderSession='';this.page=1;},
  msg(m){this.notice=m;setTimeout(()=>{this.notice='';},3500);},
  exportCSV(){const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const lines=[this.fieldNames.map(esc).join(','),...this.filteredRecords.map(r=>this.fieldNames.map(f=>esc(r[f])).join(','))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download="cbed_milk_production_records.csv";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);},
  exportAllCSV(){const esc=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const all=[...this.records].sort((a,b)=>String(a.production_date||'').localeCompare(String(b.production_date||'')));const lines=[this.fieldNames.map(esc).join(','),...all.map(r=>this.fieldNames.map(f=>esc(r[f])).join(','))];const blob=new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download="cbed_milk_production_ALL_records.csv";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);this.msg('Downloaded '+all.length+' total milk production record(s).');},
  importCSV(event){const file=event.target.files&&event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const lines=String(reader.result||'').replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2){this.msg('CSV has no data rows.');return;}const parse=line=>{const out=[];let val='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'&&quoted&&line[i+1]==='"'){val+='"';i++;}else if(ch==='"')quoted=!quoted;else if(ch===','&&!quoted){out.push(val);val='';}else val+=ch;}out.push(val);return out;};const headers=parse(lines.shift()).map(h=>h.trim().toLowerCase().replace(/[\s/-]+/g,'_'));const imported=[];lines.forEach(line=>{const vals=parse(line);const r={};this.fieldNames.forEach(f=>r[f]='');headers.forEach((h,i)=>{if(this.fieldNames.includes(h))r[h]=vals[i]??'';});if(String(r.animal_id ?? '').trim() && String(r.production_date ?? '').trim() && String(r.milking_session ?? '').trim() && String(r.milk_volume ?? '').trim() ){r.id='import-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);imported.push(r);}});if(!imported.length){this.msg('No valid rows found. Check required columns in the CSV.');return;}const prev=this.records;this.records=[...imported,...this.records];if(this.persist()){this.page=1;this.msg(imported.length+' record(s) imported.');}else this.records=prev;}catch(e){this.msg('Could not read the CSV. Check its headers and format.');}finally{event.target.value='';}};reader.onerror=()=>{this.msg('Could not read this CSV file.');event.target.value='';};reader.readAsText(file);}
 };
}
</script>
